Lemma gsi_1RB0LC_1LC0LD_0RA1LC_1RA1RD : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Jp q0 ++ [S0]) [] j A0_1RB0LC_1LC0LD_0RA1LC_1RA1RD.
