Lemma gei_1RB0LC_1LC0LD_0RA1LC_1RA1RD : forall p j q0, cview p = (j, Some q0) ->
  lift (cden (Jp q0 ++ [S0]) [] j A1_1RB0LC_1LC0LD_0RA1LC_1RA1RD) = lift (Cc (Pos.succ p)).
