Definition mk_1RB0LC_1LC0LD_0RD1LA_1RB1RD (w : Sym) (d : Dir) (n : St) : option Trans := Some (mkTrans w d n).
Local Notation mk := mk_1RB0LC_1LC0LD_0RD1LA_1RB1RD.

(** 1RB0LC_1LC0LD_0RD1LA_1RB1RD *)
(** 1RB0LC_1LC0LD_0RD1LA_1RB1RD -- the real machine (its counter grows RIGHT). *)
Definition tm_1RB0LC_1LC0LD_0RD1LA_1RB1RD : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB | StA, S1 => mk S0 DL StC
  | StB, S0 => mk S1 DL StC | StB, S1 => mk S0 DL StD
  | StC, S0 => mk S0 DR StD | StC, S1 => mk S1 DL StA
  | StD, S0 => mk S1 DR StB | StD, S1 => mk S1 DR StD end.

(** Its mirror 1LB0RC_1RC0RD_0LD1RA_1LB1LD: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_1RB0LC_1LC0LD_0RD1LA_1RB1RD : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DL StB | StA, S1 => mk S0 DR StC
  | StB, S0 => mk S1 DR StC | StB, S1 => mk S0 DR StD
  | StC, S0 => mk S0 DL StD | StC, S1 => mk S1 DR StA
  | StD, S0 => mk S1 DL StB | StD, S1 => mk S1 DL StD end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB0LC_1LC0LD_0RD1LA_1RB1RD : list Instr := [].
Definition tmw_1RB0LC_1LC0LD_0RD1LA_1RB1RD : TM := tm_wrap_trs tmm_1RB0LC_1LC0LD_0RD1LA_1RB1RD pins_1RB0LC_1LC0LD_0RD1LA_1RB1RD.
Local Notation tm := tmw_1RB0LC_1LC0LD_0RD1LA_1RB1RD.

Lemma mirror_ok_1RB0LC_1LC0LD_0RD1LA_1RB1RD : mirror_tm tm_1RB0LC_1LC0LD_0RD1LA_1RB1RD = tmm_1RB0LC_1LC0LD_0RD1LA_1RB1RD.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

