  intros p j E. destruct (Alph_01_11_011.cview_none_Alph_01_11_011 p j E) as (H1 & _).
  unfold Cc_1RB0LC_1LC0LD_0RD1LA_1RB1RD, cden, B0_1RB0LC_1LC0LD_0RD1LA_1RB1RD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_1RB0LC_1LC0LD_0RD1LA_1RB1RD : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB0LC_1LC0LD_0RD1LA_1RB1RD : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0LC_1LC0LD_0RD1LA_1RB1RD) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_01_11_011.cview_none_Alph_01_11_011 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB0LC_1LC0LD_0RD1LA_1RB1RD
             = (StD, (rep [S0;S1] (S j) ++ [S0;S1;S1], S0, [S1]))).
  { unfold cden, B1_1RB0LC_1LC0LD_0RD1LA_1RB1RD, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StD, ((rep [S0;S1] (S j) ++ [S0;S1;S1]) ++ [S0], S0, [S1]))).
  { unfold Cc_1RB0LC_1LC0LD_0RD1LA_1RB1RD. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_1RB0LC_1LC0LD_0RD1LA_1RB1RD. reflexivity.
Qed.

Lemma gsn_1RB0LC_1LC0LD_0RD1LA_1RB1RD : forall v i q0, cview v = (i, Some q0) ->
  Cin v = cden (Ip q0 ++ [S1;S1;S1]) [] i AI0_1RB0LC_1LC0LD_0RD1LA_1RB1RD.
