Lemma gen_1RB0LC_1LC0LD_0RD1LA_1RB1RD : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ip q0 ++ [S1;S1;S1]) [] i AI1_1RB0LC_1LC0LD_0RD1LA_1RB1RD) = lift (Cin (Pos.succ v)).
