Lemma lapin_1RB0LC_1LC0LD_0RD1LA_1RB1RD : forall v i q0, cview v = (i, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cin v) = Some c'
               /\ lift c' = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E.
  exists (8 * i + 8), (cden (Ip q0 ++ [S1;S1;S1]) [] i AI1_1RB0LC_1LC0LD_0RD1LA_1RB1RD).
  split; [lia|]. split; [| exact (gen_1RB0LC_1LC0LD_0RD1LA_1RB1RD v i q0 E)].
  rewrite (gsn_1RB0LC_1LC0LD_0RD1LA_1RB1RD v i q0 E).
  exact (srun_sound tm false true chn_1RB0LC_1LC0LD_0RD1LA_1RB1RD AI0_1RB0LC_1LC0LD_0RD1LA_1RB1RD AI1_1RB0LC_1LC0LD_0RD1LA_1RB1RD 8 8
