(** The chain into this family lands on its anchor up to 1/1
    trailing blanks. *)
Lemma gbo_1RB0LC_1LC0LD_0RD1LA_1RB1RD : forall j, lift (cden [] [] j BB1_1RB0LC_1LC0LD_0RD1LA_1RB1RD) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_1RB0LC_1LC0LD_0RD1LA_1RB1RD = (StD, ((rep [S1;S0] j ++ [S1;S1;S1;S1]) ++ [S0], S0, ([]) ++ [S0]))).
  { unfold cden, BB1_1RB0LC_1LC0LD_0RD1LA_1RB1RD, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StD, (rep [S1;S0] j ++ [S1;S1;S1;S1], S0, []))).
  { unfold Cin_1RB0LC_1LC0LD_0RD1LA_1RB1RD. rewrite epow2_1RB0LC_1LC0LD_0RD1LA_1RB1RD.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_1RB0LC_1LC0LD_0RD1LA_1RB1RD. rewrite ?lift_app_blank. reflexivity.
Qed.

(** This family's all-ones fill IS the next chain's start.  [cview (fill
    (pow2 j)) = (S j, None)] ([NestedLapLift.cview_fill_pow2]), so the
    family's own overflow decomposition names the word. *)
Lemma gxi_1RB0LC_1LC0LD_0RD1LA_1RB1RD : forall j, Cin (fill (pow2 j)) = cden [] [] j BE0_1RB0LC_1LC0LD_0RD1LA_1RB1RD.
Proof.
  intro j.
  destruct (ILCounter.cview_none_I (fill (pow2 j)) j (cview_fill_pow2 j)) as (H1 & _).
  unfold Cin_1RB0LC_1LC0LD_0RD1LA_1RB1RD, cden, BE0_1RB0LC_1LC0LD_0RD1LA_1RB1RD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

(** The interior lap, restated up to [lift] -- what [vis_via_ovf_lift] and
    [vis_via_fill] consume. *)
Lemma lapil_1RB0LC_1LC0LD_0RD1LA_1RB1RD : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. exact lapi_1RB0LC_1LC0LD_0RD1LA_1RB1RD. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_1RB0LC_1LC0LD_0RD1LA_1RB1RD : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_1RB0LC_1LC0LD_0RD1LA_1RB1RD p (pow2 j)).
  - exists (8 * j + 5), (cden [] [] j BB1_1RB0LC_1LC0LD_0RD1LA_1RB1RD).
    split; [lia|]. split; [| exact (gbo_1RB0LC_1LC0LD_0RD1LA_1RB1RD j)].
    rewrite (gso_1RB0LC_1LC0LD_0RD1LA_1RB1RD p j E).
    exact (srun_sound tm true true chb_1RB0LC_1LC0LD_0RD1LA_1RB1RD B0_1RB0LC_1LC0LD_0RD1LA_1RB1RD BB1_1RB0LC_1LC0LD_0RD1LA_1RB1RD 8 5
             run_boot_1RB0LC_1LC0LD_0RD1LA_1RB1RD [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (8 * j + 22), (cden [] [] j B1_1RB0LC_1LC0LD_0RD1LA_1RB1RD).
    split; [| exact (geo_1RB0LC_1LC0LD_0RD1LA_1RB1RD p j E)].
    rewrite (gxi_1RB0LC_1LC0LD_0RD1LA_1RB1RD j).
    exact (srun_sound tm true true che_1RB0LC_1LC0LD_0RD1LA_1RB1RD BE0_1RB0LC_1LC0LD_0RD1LA_1RB1RD B1_1RB0LC_1LC0LD_0RD1LA_1RB1RD 8 22
             run_exit_1RB0LC_1LC0LD_0RD1LA_1RB1RD [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_1RB0LC_1LC0LD_0RD1LA_1RB1RD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
