Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB0LC_1LC0RA_1LD0LD_0RB1LC : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0LC_1LC0RA_1LD0LD_0RB1LC) = lift (Cc (Pos.succ p)).
