(** The chain into this family lands on its anchor up to 1/0
    trailing blanks. *)
Lemma gbo_1RB0LC_1LC0RA_1LD0LD_0RB1LC : forall j, lift (cden [] [] j BB1_1RB0LC_1LC0RA_1LD0LD_0RB1LC) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_1RB0LC_1LC0RA_1LD0LD_0RB1LC = (StD, ((rep [S1;S1] j ++ [S1;S0;S1]) ++ [S0], S0, []))).
  { unfold cden, BB1_1RB0LC_1LC0RA_1LD0LD_0RB1LC, sden;
