Lemma geo_1RB0LC_1LC0RA_1LD1LC_0RB0LD : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0LC_1LC0RA_1LD1LC_0RB0LD) = lift (Cc (Pos.succ p)).
