(** The chain into this family lands on its anchor up to 1/0
    trailing blanks. *)
Lemma gbo_1RB0LC_1LC0RA_1LD1LC_0RB0LD : forall j, lift (cden [] [] j BB1_1RB0LC_1LC0RA_1LD1LC_0RB0LD) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_1RB0LC_1LC0RA_1LD1LC_0RB0LD = (StD, ((rep [S1;S1] j ++ [S1;S0;S1]) ++ [S0], S0, []))).
  { unfold cden, BB1_1RB0LC_1LC0RA_1LD1LC_0RB0LD, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
