Lemma gei_1RB0LC_1LC0RA_1LD1LC_0RB1LC : forall p j q0, cview p = (j, Some q0) ->
  cden (Jp q0 ++ [S1;S1;S0]) [] j A1_1RB0LC_1LC0RA_1LD1LC_0RB1LC = Cc (Pos.succ p).
