Lemma geo_1RB0LC_1LC0RB_0LC1LD_0RD1RA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0LC_1LC0RB_0LC1LD_0RD1RA) = lift (Cc (Pos.succ p)).
