(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_1RB0LC_1LC0RB_1LD0LD_0RA1RA : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Kp q0 ++ [S0]) [] 0 Z0_1RB0LC_1LC0RB_1LD0LD_0RA1RA /\
  lift (cden (Kp q0 ++ [S0]) [] 0 Z1_1RB0LC_1LC0RB_1LD0LD_0RA1RA) = lift (Cc (Pos.succ p)).
Proof.
  intros p q0 E. destruct (KpCounter.cview_some_K p 0 q0 E) as (H1 & H2).
  unfold Cc_1RB0LC_1LC0RB_1LD0LD_0RA1RA, cden, Z0_1RB0LC_1LC0RB_1LD0LD_0RA1RA, Z1_1RB0LC_1LC0RB_1LD0LD_0RA1RA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - cbn [rep app Nat.mul Nat.add]; rewrite ?app_nil_r.
    change ([S0]) with (([]) ++ [S0]).
    rewrite !lift_app_blank.
    rewrite H2; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gp_1RB0LC_1LC0RB_1LD0LD_0RA1RA : forall p j q0, cview p = (S j, Some q0) ->
  Cc p = cden (Kp q0 ++ [S0]) [] j P0_1RB0LC_1LC0RB_1LD0LD_0RA1RA /\
  lift (cden (Kp q0 ++ [S0]) [] j P1_1RB0LC_1LC0RB_1LD0LD_0RA1RA) = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct (KpCounter.cview_some_K p (S j) q0 E) as (H1 & H2).
  unfold Cc_1RB0LC_1LC0RB_1LD0LD_0RA1RA, cden, P0_1RB0LC_1LC0RB_1LD0LD_0RA1RA, P1_1RB0LC_1LC0RB_1LD0LD_0RA1RA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - cbn [rep app Nat.mul Nat.add]; rewrite ?app_nil_r.
    change ([S0]) with (([]) ++ [S0]).
    rewrite !lift_app_blank.
    rewrite H2; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_1RB0LC_1LC0RB_1LD0LD_0RA1RA : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct j as [|j'].
  - destruct (gz_1RB0LC_1LC0RB_1LD0LD_0RA1RA p q0 E) as (HA & HB).
    exists (0 * 0 + 4), (cden (Kp q0 ++ [S0]) [] 0 Z1_1RB0LC_1LC0RB_1LD0LD_0RA1RA).
    split; [lia|]. split; [| exact HB].
    rewrite HA.
    exact (srun_sound tm false true chz_1RB0LC_1LC0RB_1LD0LD_0RA1RA Z0_1RB0LC_1LC0RB_1LD0LD_0RA1RA Z1_1RB0LC_1LC0RB_1LD0LD_0RA1RA 0 4
             run_z_1RB0LC_1LC0RB_1LD0LD_0RA1RA (Kp q0 ++ [S0]) [] 0
             ltac:(discriminate) ltac:(reflexivity)).
  - destruct (gp_1RB0LC_1LC0RB_1LD0LD_0RA1RA p j' q0 E) as (HA & HB).
    exists (4 * j' + 8), (cden (Kp q0 ++ [S0]) [] j' P1_1RB0LC_1LC0RB_1LD0LD_0RA1RA).
    split; [lia|]. split; [| exact HB].
    rewrite HA.
    exact (srun_sound tm false true chp_1RB0LC_1LC0RB_1LD0LD_0RA1RA P0_1RB0LC_1LC0RB_1LD0LD_0RA1RA P1_1RB0LC_1LC0RB_1LD0LD_0RA1RA 4 8
             run_p_1RB0LC_1LC0RB_1LD0LD_0RA1RA (Kp q0 ++ [S0]) [] j'
             ltac:(discriminate) ltac:(reflexivity)).
Qed.

Lemma gso_1RB0LC_1LC0RB_1LD0LD_0RA1RA : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB0LC_1LC0RB_1LD0LD_0RA1RA.
Proof.
  intros p j E. destruct (KpCounter.cview_none_K p j E) as (H1 & _).
  unfold Cc_1RB0LC_1LC0RB_1LD0LD_0RA1RA, cden, B0_1RB0LC_1LC0RB_1LD0LD_0RA1RA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_1RB0LC_1LC0RB_1LD0LD_0RA1RA : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB0LC_1LC0RB_1LD0LD_0RA1RA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0LC_1LC0RB_1LD0LD_0RA1RA) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (KpCounter.cview_none_K p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB0LC_1LC0RB_1LD0LD_0RA1RA
             = (StA, (rep [S0] (S j) ++ [S1], S0, ([]) ++ [S0]))).
  { unfold cden, B1_1RB0LC_1LC0RB_1LD0LD_0RA1RA, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StA, ((rep [S0] (S j) ++ [S1]) ++ [S0], S0, []))).
  { unfold Cc_1RB0LC_1LC0RB_1LD0LD_0RA1RA. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
