  - destruct (lapi_1RB0LC_1LC0RB_1RD1LA_1LD0LA p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB0LC_1LC0RB_1RD1LA_1LD0LA B0_1RB0LC_1LC0RB_1RD1LA_1LD0LA B1_1RB0LC_1LC0RB_1RD1LA_1LD0LA 10 24 p j' [] []).
    + exact run_ovf_1RB0LC_1LC0RB_1RD1LA_1LD0LA.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB0LC_1LC0RB_1RD1LA_1LD0LA p j' E).
    + exact (geo_1RB0LC_1LC0RB_1RD1LA_1LD0LA p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_1RB0LC_1LC0RB_1RD1LA_1LD0LA : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 28.
  assert (H : match csteps tm 28 c0 with
