    [exact Hst | reflexivity | reflexivity | exact (gso_1RB0LC_1LC0RB_1RD1LA_1LD0LA p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB0LC_1LC0RB_1RD1LA_1LD0LA : forall t, ~ In t pins_1RB0LC_1LC0RB_1RD1LA_1LD0LA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB0LC_1LC0RB_1RD1LA_1LD0LA.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_1RB0LC_1LC0RB_1RD1LA_1LD0LA
      with (l := [SWin 2; SCycL 7 0; SWin 1]).
    vm_compute; reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_1RB0LC_1LC0RB_1RD1LA_1LD0LA
      with (l := [SWin 2; SCycL 7 0; SWin 4]).
    vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB0LC_1LC0RB_1RD1LA_1LD0LA
      with (l := [SWin 2; SCycL 7 0; SWin 2]).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB0LC_1LC0RB_1RD1LA_1LD0LA
      with (l := [SWin 2; SCycL 7 0; SWin 7; SWinL 5]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB0LC_1LC0RB_1RD1LA_1LD0LA
      with (l := []).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB0LC_1LC0RB_1RD1LA_1LD0LA
      with (l := [SWin 2; SCycL 7 0; SWin 3]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB0LC_1LC0RB_1RD1LA_1LD0LA
      with (l := [SWin 1]).
    vm_compute; reflexivity.
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_1RB0LC_1LC0RB_1RD1LA_1LD0LA
      with (l := [SWin 2]).
    vm_compute; reflexivity.
Qed.

Theorem nqhtr_1RB0LC_1LC0RB_1RD1LA_1LD0LA : NeverQuasiHaltsTr tm_1RB0LC_1LC0RB_1RD1LA_1LD0LA.
Proof.
  apply (glue_neverqhtr tm_1RB0LC_1LC0RB_1RD1LA_1LD0LA pins_1RB0LC_1LC0RB_1RD1LA_1LD0LA Cc 1).
  - exact boot_1RB0LC_1LC0RB_1RD1LA_1LD0LA.
