    exact (srun_sound tm true true chb_1RB0LC_1LC0RD_1RA1LA_1RB0LA B0_1RB0LC_1LC0RD_1RA1LA_1RB0LA BB1_1RB0LC_1LC0RD_1RA1LA_1RB0LA 4 8
             run_boot_1RB0LC_1LC0RD_1RA1LA_1RB0LA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (fire_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (fire_of_run_instr tm (fun _ : positive => Cin (fill (pow2 j)))
                      true true l BE0_1RB0LC_1LC0RD_1RA1LA_1RB0LA xH j [] []);
      [exact Hst | reflexivity | reflexivity | exact (gxi_1RB0LC_1LC0RD_1RA1LA_1RB0LA j)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB0LC_1LC0RD_1RA1LA_1RB0LA : forall t, ~ In t pins_1RB0LC_1LC0RD_1RA1LA_1RB0LA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n c', 0 < n /\ csteps tm n (Cc p0) = Some c'
                         /\ lift c' = lift (Cc (Pos.succ p0)))
    by exact lapi_1RB0LC_1LC0RD_1RA1LA_1RB0LA.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LC_1LC0RD_1RA1LA_1RB0LA [] (StA, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* A1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LC_1LC0RD_1RA1LA_1RB0LA [SWinR 2; SCycL 2 0; SWin 1] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B0 *)
