  assert (HD : cden [] [] j BB1_1RB0LC_1LC0RD_1RD1LA_1RB0LD = (StD, (rep [S1;S0] j ++ [S1;S1], S0, ([]) ++ [S0]))).
  { unfold cden, BB1_1RB0LC_1LC0RD_1RD1LA_1RB0LD, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
