    reflexivity. }
  assert (HC : Cin (pow2 j) = (StD, (rep [S1;S0] j ++ [S1;S1], S0, []))).
  { unfold Cin_1RB0LC_1LC0RD_1RD1LA_1RB0LD. rewrite epow2_1RB0LC_1LC0RD_1RD1LA_1RB0LD.
    first [ rewrite <- app_assoc; reflexivity
