    exact (srun_sound tm true true chb_1RB0LC_1LC1RA_0RA1LD_1LC0RC B0_1RB0LC_1LC1RA_0RA1LD_1LC0RC BB1_1RB0LC_1LC1RA_0RA1LD_1LC0RC 6 6
             run_boot_1RB0LC_1LC1RA_0RA1LD_1LC0RC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (fire_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (fire_of_run_instr tm (fun _ : positive => Cin (fill (pow2 j)))
                      true true l BE0_1RB0LC_1LC1RA_0RA1LD_1LC0RC xH j [] []);
      [exact Hst | reflexivity | reflexivity | exact (gxi_1RB0LC_1LC1RA_0RA1LD_1LC0RC j)].
