Definition chn_1RB0LC_1LC1RA_0RA1LD_1RB1LC : list lstep := [SCycL 2 0; SWin 4; SCycR 2; SWin 2; SWinR 14].

Lemma run_inner_1RB0LC_1LC1RA_0RA1LD_1RB1LC : srun tm false true chn_1RB0LC_1LC1RA_0RA1LD_1RB1LC AI0_1RB0LC_1LC1RA_0RA1LD_1RB1LC = Some (AI1_1RB0LC_1LC1RA_0RA1LD_1RB1LC, 4, 20).
Proof. vm_compute. reflexivity. Qed.

(** *** boot: the outer overflow anchor -> the first inner anchor at [pow2 j] *)
Definition BB1_1RB0LC_1LC1RA_0RA1LD_1RB1LC : sconf := mkC StA (mkS [] [S1;S1] 1 0 [S1;S1]) S0 (mkS [S1;S1;S0] [] 0 0 []).
Definition chb_1RB0LC_1LC1RA_0RA1LD_1RB1LC : list lstep := [SCycL 2 0; SWin 2; SWinL 4; SCycR 2; SWinR 2; SRotL 1; SWin 3; SWinR 6].

Lemma run_boot_1RB0LC_1LC1RA_0RA1LD_1RB1LC : srun tm true true chb_1RB0LC_1LC1RA_0RA1LD_1RB1LC B0_1RB0LC_1LC1RA_0RA1LD_1RB1LC = Some (BB1_1RB0LC_1LC1RA_0RA1LD_1RB1LC, 4, 17).
