    exact (srun_sound tm true true chb_1RB0LC_1LC1RA_0RA1LD_1RC1LC B0_1RB0LC_1LC1RA_0RA1LD_1RC1LC BB1_1RB0LC_1LC1RA_0RA1LD_1RC1LC 4 8
