Definition mk_1RB0LC_1LC1RA_0RB1LD_0RD1LC (w : Sym) (d : Dir) (n : St) : option Trans := Some (mkTrans w d n).
Local Notation mk := mk_1RB0LC_1LC1RA_0RB1LD_0RD1LC.

(** 1RB0LC_1LC1RA_0RB1LD_0RD1LC *)
(** 1RB0LC_1LC1RA_0RB1LD_0RD1LC -- the real machine (its counter grows RIGHT). *)
Definition tm_1RB0LC_1LC1RA_0RB1LD_0RD1LC : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB | StA, S1 => mk S0 DL StC
  | StB, S0 => mk S1 DL StC | StB, S1 => mk S1 DR StA
  | StC, S0 => mk S0 DR StB | StC, S1 => mk S1 DL StD
  | StD, S0 => mk S0 DR StD | StD, S1 => mk S1 DL StC end.

(** Its mirror 1LB0RC_1RC1LA_0LB1RD_0LD1RC: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_1RB0LC_1LC1RA_0RB1LD_0RD1LC : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DL StB | StA, S1 => mk S0 DR StC
  | StB, S0 => mk S1 DR StC | StB, S1 => mk S1 DL StA
  | StC, S0 => mk S0 DL StB | StC, S1 => mk S1 DR StD
  | StD, S0 => mk S0 DL StD | StD, S1 => mk S1 DR StC end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB0LC_1LC1RA_0RB1LD_0RD1LC : list Instr := [].
Definition tmw_1RB0LC_1LC1RA_0RB1LD_0RD1LC : TM := tm_wrap_trs tmm_1RB0LC_1LC1RA_0RB1LD_0RD1LC pins_1RB0LC_1LC1RA_0RB1LD_0RD1LC.
Local Notation tm := tmw_1RB0LC_1LC1RA_0RB1LD_0RD1LC.

Lemma mirror_ok_1RB0LC_1LC1RA_0RB1LD_0RD1LC : mirror_tm tm_1RB0LC_1LC1RA_0RB1LD_0RD1LC = tmm_1RB0LC_1LC1RA_0RB1LD_0RD1LC.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

