(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB0LC_1LC1RA_0RB1LD_0RD1LC : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Jp q0 ++ [S0]) [] j A0_1RB0LC_1LC1RA_0RB1LD_0RD1LC.
Proof.
  intros p j q0 E. destruct (JpCounter.cview_some_J p j q0 E) as (H1 & _).
  unfold Cc_1RB0LC_1LC1RA_0RB1LD_0RD1LC, cden, A0_1RB0LC_1LC1RA_0RB1LD_0RD1LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S0] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gei_1RB0LC_1LC1RA_0RB1LD_0RD1LC : forall p j q0, cview p = (j, Some q0) ->
  cden (Jp q0 ++ [S0]) [] j A1_1RB0LC_1LC1RA_0RB1LD_0RD1LC = Cc (Pos.succ p).
Proof.
  intros p j q0 E. destruct (JpCounter.cview_some_J p j q0 E) as (_ & H2).
  unfold Cc_1RB0LC_1LC1RA_0RB1LD_0RD1LC, cden, A1_1RB0LC_1LC1RA_0RB1LD_0RD1LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_1RB0LC_1LC1RA_0RB1LD_0RD1LC : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. exists (4 * j + 6). split; [lia|].
  rewrite (gsi_1RB0LC_1LC1RA_0RB1LD_0RD1LC p j q0 E).
  rewrite (srun_sound tm false true chi_1RB0LC_1LC1RA_0RB1LD_0RD1LC A0_1RB0LC_1LC1RA_0RB1LD_0RD1LC A1_1RB0LC_1LC1RA_0RB1LD_0RD1LC 4 6
             run_int_1RB0LC_1LC1RA_0RB1LD_0RD1LC (Jp q0 ++ [S0]) [] j
             ltac:(discriminate) ltac:(reflexivity)).
  f_equal. exact (gei_1RB0LC_1LC1RA_0RB1LD_0RD1LC p j q0 E).
Qed.

Lemma gso_1RB0LC_1LC1RA_0RB1LD_0RD1LC : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB0LC_1LC1RA_0RB1LD_0RD1LC.
Proof.
  intros p j E. destruct (JpCounter.cview_none_J p j E) as (H1 & _).
  unfold Cc_1RB0LC_1LC1RA_0RB1LD_0RD1LC, cden, B0_1RB0LC_1LC1RA_0RB1LD_0RD1LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_1RB0LC_1LC1RA_0RB1LD_0RD1LC : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB0LC_1LC1RA_0RB1LD_0RD1LC : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0LC_1LC1RA_0RB1LD_0RD1LC) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (JpCounter.cview_none_J p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB0LC_1LC1RA_0RB1LD_0RD1LC
             = (StC, (rep [S1;S1] (S j) ++ [S1], S0, []))).
  { unfold cden, B1_1RB0LC_1LC1RA_0RB1LD_0RD1LC, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StC, ((rep [S1;S1] (S j) ++ [S1]) ++ [S0], S0, []))).
  { unfold Cc_1RB0LC_1LC1RA_0RB1LD_0RD1LC. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_1RB0LC_1LC1RA_0RB1LD_0RD1LC. reflexivity.
Qed.

(** ** The lap *)

Lemma lap_1RB0LC_1LC1RA_0RB1LD_0RD1LC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB0LC_1LC1RA_0RB1LD_0RD1LC p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB0LC_1LC1RA_0RB1LD_0RD1LC B0_1RB0LC_1LC1RA_0RB1LD_0RD1LC B1_1RB0LC_1LC1RA_0RB1LD_0RD1LC 4 6 p j' [] []).
    + exact run_ovf_1RB0LC_1LC1RA_0RB1LD_0RD1LC.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB0LC_1LC1RA_0RB1LD_0RD1LC p j' E).
    + exact (geo_1RB0LC_1LC1RA_0RB1LD_0RD1LC p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_1RB0LC_1LC1RA_0RB1LD_0RD1LC : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 11.
  assert (H : match csteps tm 11 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 11 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB0LC_1LC1RA_0RB1LD_0RD1LC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0LC_1LC1RA_0RB1LD_0RD1LC = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB0LC_1LC1RA_0RB1LD_0RD1LC p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB0LC_1LC1RA_0RB1LD_0RD1LC p j E)].
Qed.


(** An instruction that fires ONLY inside the interior lap: [vis_via_ovf] runs to an
    OVERFLOW anchor, so it cannot see one.  This is the interior witness, and
    [LapCertGlueLift.fire_via_int_lift] carries it to every anchor. *)
Lemma firei_1RB0LC_1LC1RA_0RB1LD_0RD1LC : forall (l : list lstep) (t : Instr),
  srun_instr tm false true l A0_1RB0LC_1LC1RA_0RB1LD_0RD1LC = Some t ->
  forall p j q0, cview p = (j, Some q0) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j q0 E.
  apply (fire_of_run_instr tm Cc false true l A0_1RB0LC_1LC1RA_0RB1LD_0RD1LC p j (Jp q0 ++ [S0]) []);
    [exact Hst | discriminate | reflexivity | exact (gsi_1RB0LC_1LC1RA_0RB1LD_0RD1LC p j q0 E)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB0LC_1LC1RA_0RB1LD_0RD1LC : forall t, ~ In t pins_1RB0LC_1LC1RA_0RB1LD_0RD1LC ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB0LC_1LC1RA_0RB1LD_0RD1LC.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_1RB0LC_1LC1RA_0RB1LD_0RD1LC
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 1]).
    vm_compute; reflexivity.
  - (* A1: fires only in the interior lap *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_int_lift tm Cc lap_1RB0LC_1LC1RA_0RB1LD_0RD1LC (StA, S1)).
    intros p1 j1 r1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (firei_1RB0LC_1LC1RA_0RB1LD_0RD1LC [SRotL 1; SWin 1; SCycL 2 0; SWin 1] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 r1 E1).
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB0LC_1LC1RA_0RB1LD_0RD1LC
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 1]).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB0LC_1LC1RA_0RB1LD_0RD1LC
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB0LC_1LC1RA_0RB1LD_0RD1LC
      with (l := []).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB0LC_1LC1RA_0RB1LD_0RD1LC
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 2]).
    vm_compute; reflexivity.
  - (* D0: fires only in the interior lap *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_int_lift tm Cc lap_1RB0LC_1LC1RA_0RB1LD_0RD1LC (StD, S0)).
    intros p1 j1 r1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (firei_1RB0LC_1LC1RA_0RB1LD_0RD1LC [SRotL 1; SWin 1; SCycL 2 0; SWin 2; SCycR 2; SWin 1] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 r1 E1).
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_1RB0LC_1LC1RA_0RB1LD_0RD1LC
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 3]).
    vm_compute; reflexivity.
Qed.

Theorem nqhtrm_1RB0LC_1LC1RA_0RB1LD_0RD1LC : NeverQuasiHaltsTr tmm_1RB0LC_1LC1RA_0RB1LD_0RD1LC.
Proof.
  apply (glue_neverqhtr tmm_1RB0LC_1LC1RA_0RB1LD_0RD1LC pins_1RB0LC_1LC1RA_0RB1LD_0RD1LC Cc 1).
  - exact boot_1RB0LC_1LC1RA_0RB1LD_0RD1LC.
  - intros p _. apply lap_1RB0LC_1LC1RA_0RB1LD_0RD1LC.
  - intros t Ht p _. apply fire_1RB0LC_1LC1RA_0RB1LD_0RD1LC. exact Ht.
Qed.

Theorem nqhtr_1RB0LC_1LC1RA_0RB1LD_0RD1LC : NeverQuasiHaltsTr tm_1RB0LC_1LC1RA_0RB1LD_0RD1LC.
Proof. apply (neverqhtr_mirror tm_1RB0LC_1LC1RA_0RB1LD_0RD1LC). rewrite mirror_ok_1RB0LC_1LC1RA_0RB1LD_0RD1LC. exact nqhtrm_1RB0LC_1LC1RA_0RB1LD_0RD1LC. Qed.

Theorem nonhalt_1RB0LC_1LC1RA_0RB1LD_0RD1LC : NonHalt tm_1RB0LC_1LC1RA_0RB1LD_0RD1LC.
Proof. apply never_qh_tr_nonhalt, nqhtr_1RB0LC_1LC1RA_0RB1LD_0RD1LC. Qed.

End LAPT_1RB0LC_1LC1RA_0RB1LD_0RD1LC.

