Lemma gsi_1RB0LC_1LC1RA_0RD1LC_1RB0LC : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Jp q0 ++ [S0]) [] j A0_1RB0LC_1LC1RA_0RD1LC_1RB0LC.
