Lemma gp_1RB0LC_1LC1RB_0RA1LD_0RA0LC : forall p j q0, cview p = (S j, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j P0_1RB0LC_1LC1RB_0RA1LD_0RA0LC /\
