Definition tmw_1RB0LC_1LC1RB_0RA1LD_0RA1LA : TM := tm_wrap_trs tmm_1RB0LC_1LC1RB_0RA1LD_0RA1LA pins_1RB0LC_1LC1RB_0RA1LD_0RA1LA.
Local Notation tm := tmw_1RB0LC_1LC1RB_0RA1LD_0RA1LA.

Lemma mirror_ok_1RB0LC_1LC1RB_0RA1LD_0RA1LA : mirror_tm tm_1RB0LC_1LC1RB_0RA1LD_0RA1LA = tmm_1RB0LC_1LC1RB_0RA1LD_0RA1LA.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

Definition Cc_1RB0LC_1LC1RB_0RA1LD_0RA1LA (p : positive) : cconf := (StD, (Ap_Alph_101_111_11 p ++ [S0], S0, [])).
Local Notation Cc := Cc_1RB0LC_1LC1RB_0RA1LD_0RA1LA.

(** ** The certificate *)

(** j = 0: the repeated block is absent, so the whole lap is concrete. *)
Definition Z0_1RB0LC_1LC1RB_0RA1LD_0RA1LA : sconf := mkC StD (mkS [S1;S0;S1] [] 0 0 []) S0 (mkS [] [] 0 0 []).
Definition Z1_1RB0LC_1LC1RB_0RA1LD_0RA1LA : sconf := mkC StD (mkS [S1;S1;S1] [] 0 0 []) S0 (mkS [] [] 0 0 []).
Definition chz_1RB0LC_1LC1RB_0RA1LD_0RA1LA : list lstep := [SWin 6].

Lemma run_z_1RB0LC_1LC1RB_0RA1LD_0RA1LA : srun tm false true chz_1RB0LC_1LC1RB_0RA1LD_0RA1LA Z0_1RB0LC_1LC1RB_0RA1LD_0RA1LA = Some (Z1_1RB0LC_1LC1RB_0RA1LD_0RA1LA, 0, 6).
Proof. vm_compute. reflexivity. Qed.

(** j = S j': one copy of the unit sits in the PREFIX, so the head always has
    a concrete cell to step onto. *)
Definition P0_1RB0LC_1LC1RB_0RA1LD_0RA1LA : sconf := mkC StD (mkS [S1;S1;S1] [S1;S1;S1] 1 0 [S1;S0;S1]) S0 (mkS [] [] 0 0 []).
Definition P1_1RB0LC_1LC1RB_0RA1LD_0RA1LA : sconf := mkC StD (mkS [S1;S0;S1] [S1;S0;S1] 1 0 [S1;S1;S1]) S0 (mkS [] [] 0 0 []).
Definition chp_1RB0LC_1LC1RB_0RA1LD_0RA1LA : list lstep := [SWin 5; SCycL 3 0; SWin 4; SCycR 3; SWin 3].

Lemma run_p_1RB0LC_1LC1RB_0RA1LD_0RA1LA : srun tm false true chp_1RB0LC_1LC1RB_0RA1LD_0RA1LA P0_1RB0LC_1LC1RB_0RA1LD_0RA1LA = Some (P1_1RB0LC_1LC1RB_0RA1LD_0RA1LA, 6, 12).
Proof. vm_compute. reflexivity. Qed.

Definition B0_1RB0LC_1LC1RB_0RA1LD_0RA1LA : sconf := mkC StD (mkS [] [S1;S1;S1] 1 0 [S1;S1;S0]) S0 (mkS [] [] 0 0 []).
Definition B1_1RB0LC_1LC1RB_0RA1LD_0RA1LA : sconf := mkC StD (mkS [] [S1;S0;S1] 1 1 [S1;S1]) S0 (mkS [] [] 0 0 []).
(** ** The INNER anchor family -- Ap_Alph_110_111_1 at StA *)
Definition Cin_1RB0LC_1LC1RB_0RA1LD_0RA1LA (v : positive) : cconf := (StA, (Ap_Alph_110_111_1 v ++ [S1;S1], S0, [])).
Local Notation Cin := Cin_1RB0LC_1LC1RB_0RA1LD_0RA1LA.

(** [E (2^n) = A^n C]: the value this family's count starts at. *)
Lemma epow2_1RB0LC_1LC1RB_0RA1LD_0RA1LA : forall n, Ap_Alph_110_111_1 (pow2 n) = rep [S1;S1;S0] n ++ [S1].
Proof. induction n; simpl; [reflexivity | rewrite IHn; reflexivity]. Qed.

(** Its own INTERIOR lap -- ordinary and affine.  Iterating it to the fill is
    where a [Theta(2^j)] lives, and [inner_to_fill_lift] keeps it inside an
    existential. *)
Definition AI0_1RB0LC_1LC1RB_0RA1LD_0RA1LA : sconf := mkC StA (mkS [] [S1;S1;S1] 1 0 [S1;S1;S0]) S0 (mkS [] [] 0 0 []).
Definition AI1_1RB0LC_1LC1RB_0RA1LD_0RA1LA : sconf := mkC StA (mkS [] [S1;S1;S0] 1 0 [S1;S1;S1]) S0 (mkS [S0] [] 0 0 []).
Definition chn_1RB0LC_1LC1RB_0RA1LD_0RA1LA : list lstep := [SRotL 1; SWin 1; SCycL 3 0; SWin 4; SCycR 3; SWin 1; SWinR 2; SUnrotL 1].

Lemma run_inner_1RB0LC_1LC1RB_0RA1LD_0RA1LA : srun tm false true chn_1RB0LC_1LC1RB_0RA1LD_0RA1LA AI0_1RB0LC_1LC1RB_0RA1LD_0RA1LA = Some (AI1_1RB0LC_1LC1RB_0RA1LD_0RA1LA, 6, 8).
Proof. vm_compute. reflexivity. Qed.

(** *** boot: the outer overflow anchor -> the first inner anchor at [pow2 j] *)
Definition BB1_1RB0LC_1LC1RB_0RA1LD_0RA1LA : sconf := mkC StA (mkS [] [S1;S1;S0] 1 0 [S1;S1;S1]) S0 (mkS [] [] 0 0 []).
Definition chb_1RB0LC_1LC1RB_0RA1LD_0RA1LA : list lstep := [SRotL 1; SWin 3; SRotL 1; SWin 1; SCycL 3 0; SWin 2; SCycR 3; SWin 2; SUnrotL 2].

Lemma run_boot_1RB0LC_1LC1RB_0RA1LD_0RA1LA : srun tm true true chb_1RB0LC_1LC1RB_0RA1LD_0RA1LA B0_1RB0LC_1LC1RB_0RA1LD_0RA1LA = Some (BB1_1RB0LC_1LC1RB_0RA1LD_0RA1LA, 6, 8).
Proof. vm_compute. reflexivity. Qed.

(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_1RB0LC_1LC1RB_0RA1LD_0RA1LA : sconf := mkC StA (mkS [] [S1;S1;S1] 1 0 [S1;S1;S1]) S0 (mkS [] [] 0 0 []).
Definition che_1RB0LC_1LC1RB_0RA1LD_0RA1LA : list lstep := [SRotL 1; SWin 1; SCycL 3 0; SWin 2; SWinL 4; SCycR 3; SWin 1; SWinR 1; SRotL 1; SFoldL 1].

Lemma run_exit_1RB0LC_1LC1RB_0RA1LD_0RA1LA : srun tm true true che_1RB0LC_1LC1RB_0RA1LD_0RA1LA BE0_1RB0LC_1LC1RB_0RA1LD_0RA1LA = Some (B1_1RB0LC_1LC1RB_0RA1LD_0RA1LA, 6, 9).
Proof. vm_compute. reflexivity. Qed.

(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_1RB0LC_1LC1RB_0RA1LD_0RA1LA : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Ap_Alph_101_111_11 q0 ++ [S0]) [] 0 Z0_1RB0LC_1LC1RB_0RA1LD_0RA1LA /\
  cden (Ap_Alph_101_111_11 q0 ++ [S0]) [] 0 Z1_1RB0LC_1LC1RB_0RA1LD_0RA1LA = Cc (Pos.succ p).
Proof.
  intros p q0 E. destruct (Alph_101_111_11.cview_some_Alph_101_111_11 p 0 q0 E) as (H1 & H2).
  unfold Cc_1RB0LC_1LC1RB_0RA1LD_0RA1LA, cden, Z0_1RB0LC_1LC1RB_0RA1LD_0RA1LA, Z1_1RB0LC_1LC1RB_0RA1LD_0RA1LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gp_1RB0LC_1LC1RB_0RA1LD_0RA1LA : forall p j q0, cview p = (S j, Some q0) ->
  Cc p = cden (Ap_Alph_101_111_11 q0 ++ [S0]) [] j P0_1RB0LC_1LC1RB_0RA1LD_0RA1LA /\
  cden (Ap_Alph_101_111_11 q0 ++ [S0]) [] j P1_1RB0LC_1LC1RB_0RA1LD_0RA1LA = Cc (Pos.succ p).
Proof.
  intros p j q0 E. destruct (Alph_101_111_11.cview_some_Alph_101_111_11 p (S j) q0 E) as (H1 & H2).
  unfold Cc_1RB0LC_1LC1RB_0RA1LD_0RA1LA, cden, P0_1RB0LC_1LC1RB_0RA1LD_0RA1LA, P1_1RB0LC_1LC1RB_0RA1LD_0RA1LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_1RB0LC_1LC1RB_0RA1LD_0RA1LA : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct j as [|j'].
  - destruct (gz_1RB0LC_1LC1RB_0RA1LD_0RA1LA p q0 E) as (HA & HB).
    exists (0 * 0 + 6). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chz_1RB0LC_1LC1RB_0RA1LD_0RA1LA Z0_1RB0LC_1LC1RB_0RA1LD_0RA1LA Z1_1RB0LC_1LC1RB_0RA1LD_0RA1LA 0 6
               run_z_1RB0LC_1LC1RB_0RA1LD_0RA1LA (Ap_Alph_101_111_11 q0 ++ [S0]) [] 0
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
  - destruct (gp_1RB0LC_1LC1RB_0RA1LD_0RA1LA p j' q0 E) as (HA & HB).
    exists (6 * j' + 12). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_1RB0LC_1LC1RB_0RA1LD_0RA1LA P0_1RB0LC_1LC1RB_0RA1LD_0RA1LA P1_1RB0LC_1LC1RB_0RA1LD_0RA1LA 6 12
               run_p_1RB0LC_1LC1RB_0RA1LD_0RA1LA (Ap_Alph_101_111_11 q0 ++ [S0]) [] j'
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
Qed.

Lemma gso_1RB0LC_1LC1RB_0RA1LD_0RA1LA : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB0LC_1LC1RB_0RA1LD_0RA1LA.
Proof.
  intros p j E. destruct (Alph_101_111_11.cview_none_Alph_101_111_11 p j E) as (H1 & _).
  unfold Cc_1RB0LC_1LC1RB_0RA1LD_0RA1LA, cden, B0_1RB0LC_1LC1RB_0RA1LD_0RA1LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_1RB0LC_1LC1RB_0RA1LD_0RA1LA : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB0LC_1LC1RB_0RA1LD_0RA1LA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0LC_1LC1RB_0RA1LD_0RA1LA) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_101_111_11.cview_none_Alph_101_111_11 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB0LC_1LC1RB_0RA1LD_0RA1LA
             = (StD, (rep [S1;S0;S1] (S j) ++ [S1;S1], S0, []))).
  { unfold cden, B1_1RB0LC_1LC1RB_0RA1LD_0RA1LA, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StD, ((rep [S1;S0;S1] (S j) ++ [S1;S1]) ++ [S0], S0, []))).
  { unfold Cc_1RB0LC_1LC1RB_0RA1LD_0RA1LA. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_1RB0LC_1LC1RB_0RA1LD_0RA1LA. reflexivity.
Qed.

Lemma gsn_1RB0LC_1LC1RB_0RA1LD_0RA1LA : forall v i q0, cview v = (i, Some q0) ->
  Cin v = cden (Ap_Alph_110_111_1 q0 ++ [S1;S1]) [] i AI0_1RB0LC_1LC1RB_0RA1LD_0RA1LA.
Proof.
  intros v i q0 E. destruct (Alph_110_111_1.cview_some_Alph_110_111_1 v i q0 E) as (H1 & _).
  unfold Cin_1RB0LC_1LC1RB_0RA1LD_0RA1LA, cden, AI0_1RB0LC_1LC1RB_0RA1LD_0RA1LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1;S1] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gen_1RB0LC_1LC1RB_0RA1LD_0RA1LA : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ap_Alph_110_111_1 q0 ++ [S1;S1]) [] i AI1_1RB0LC_1LC1RB_0RA1LD_0RA1LA) = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E. destruct (Alph_110_111_1.cview_some_Alph_110_111_1 v i q0 E) as (_ & H2).
  unfold Cin_1RB0LC_1LC1RB_0RA1LD_0RA1LA, cden, AI1_1RB0LC_1LC1RB_0RA1LD_0RA1LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  replace (0 * i + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  change ([S0]) with (([]) ++ [S0]).
  rewrite !lift_app_blank.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S1;S0] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapin_1RB0LC_1LC1RB_0RA1LD_0RA1LA : forall v i q0, cview v = (i, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cin v) = Some c'
               /\ lift c' = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E.
  exists (6 * i + 8), (cden (Ap_Alph_110_111_1 q0 ++ [S1;S1]) [] i AI1_1RB0LC_1LC1RB_0RA1LD_0RA1LA).
  split; [lia|]. split; [| exact (gen_1RB0LC_1LC1RB_0RA1LD_0RA1LA v i q0 E)].
  rewrite (gsn_1RB0LC_1LC1RB_0RA1LD_0RA1LA v i q0 E).
  exact (srun_sound tm false true chn_1RB0LC_1LC1RB_0RA1LD_0RA1LA AI0_1RB0LC_1LC1RB_0RA1LD_0RA1LA AI1_1RB0LC_1LC1RB_0RA1LD_0RA1LA 6 8
           run_inner_1RB0LC_1LC1RB_0RA1LD_0RA1LA (Ap_Alph_110_111_1 q0 ++ [S1;S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

(** The chain into this family lands on its anchor up to 0/0
    trailing blanks. *)
Lemma gbo_1RB0LC_1LC1RB_0RA1LD_0RA1LA : forall j, lift (cden [] [] j BB1_1RB0LC_1LC1RB_0RA1LD_0RA1LA) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_1RB0LC_1LC1RB_0RA1LD_0RA1LA = (StA, (rep [S1;S1;S0] j ++ [S1;S1;S1], S0, []))).
  { unfold cden, BB1_1RB0LC_1LC1RB_0RA1LD_0RA1LA, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StA, (rep [S1;S1;S0] j ++ [S1;S1;S1], S0, []))).
  { unfold Cin_1RB0LC_1LC1RB_0RA1LD_0RA1LA. rewrite epow2_1RB0LC_1LC1RB_0RA1LD_0RA1LA.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_1RB0LC_1LC1RB_0RA1LD_0RA1LA. rewrite ?lift_app_blank. reflexivity.
Qed.

(** This family's all-ones fill IS the next chain's start.  [cview (fill
    (pow2 j)) = (S j, None)] ([NestedLapLift.cview_fill_pow2]), so the
    family's own overflow decomposition names the word. *)
Lemma gxi_1RB0LC_1LC1RB_0RA1LD_0RA1LA : forall j, Cin (fill (pow2 j)) = cden [] [] j BE0_1RB0LC_1LC1RB_0RA1LD_0RA1LA.
Proof.
  intro j.
  destruct (Alph_110_111_1.cview_none_Alph_110_111_1 (fill (pow2 j)) j (cview_fill_pow2 j)) as (H1 & _).
  unfold Cin_1RB0LC_1LC1RB_0RA1LD_0RA1LA, cden, BE0_1RB0LC_1LC1RB_0RA1LD_0RA1LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

(** The interior lap, restated up to [lift] -- what [vis_via_ovf_lift] and
    [vis_via_fill] consume. *)
Lemma lapil_1RB0LC_1LC1RB_0RA1LD_0RA1LA : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. intros p j q0 E. destruct (lapi_1RB0LC_1LC1RB_0RA1LD_0RA1LA p j q0 E) as (n & Hn & Hr).
  exists n, (Cc (Pos.succ p)).
  split; [exact Hn | split; [exact Hr | reflexivity]]. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_1RB0LC_1LC1RB_0RA1LD_0RA1LA : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_1RB0LC_1LC1RB_0RA1LD_0RA1LA p (pow2 j)).
  - exists (6 * j + 8), (cden [] [] j BB1_1RB0LC_1LC1RB_0RA1LD_0RA1LA).
    split; [lia|]. split; [| exact (gbo_1RB0LC_1LC1RB_0RA1LD_0RA1LA j)].
    rewrite (gso_1RB0LC_1LC1RB_0RA1LD_0RA1LA p j E).
    exact (srun_sound tm true true chb_1RB0LC_1LC1RB_0RA1LD_0RA1LA B0_1RB0LC_1LC1RB_0RA1LD_0RA1LA BB1_1RB0LC_1LC1RB_0RA1LD_0RA1LA 6 8
             run_boot_1RB0LC_1LC1RB_0RA1LD_0RA1LA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (6 * j + 9), (cden [] [] j B1_1RB0LC_1LC1RB_0RA1LD_0RA1LA).
    split; [| exact (geo_1RB0LC_1LC1RB_0RA1LD_0RA1LA p j E)].
    rewrite (gxi_1RB0LC_1LC1RB_0RA1LD_0RA1LA j).
    exact (srun_sound tm true true che_1RB0LC_1LC1RB_0RA1LD_0RA1LA BE0_1RB0LC_1LC1RB_0RA1LD_0RA1LA B1_1RB0LC_1LC1RB_0RA1LD_0RA1LA 6 9
             run_exit_1RB0LC_1LC1RB_0RA1LD_0RA1LA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_1RB0LC_1LC1RB_0RA1LD_0RA1LA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB0LC_1LC1RB_0RA1LD_0RA1LA p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_1RB0LC_1LC1RB_0RA1LD_0RA1LA p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_1RB0LC_1LC1RB_0RA1LD_0RA1LA : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 3.
  assert (H : match csteps tm 3 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 3 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB0LC_1LC1RB_0RA1LD_0RA1LA : forall (l : list lstep) (t : Instr),
