  { unfold cden, BB1_1RB0LC_1LC1RB_0RA1LD_0RB1LA, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StB, (rep [S1;S1;S0] j ++ [S1;S1;S1], S0, [S1]))).
  { unfold Cin_1RB0LC_1LC1RB_0RA1LD_0RB1LA. rewrite epow2_1RB0LC_1LC1RB_0RA1LD_0RB1LA.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
