(** ** The lap *)

Lemma lap_1RB0LC_1LC1RB_0RA1LD_1RD1LA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
