  - destruct (lapi_1RB0LC_1LC1RB_0RA1LD_1RD1LA p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB0LC_1LC1RB_0RA1LD_1RD1LA B0_1RB0LC_1LC1RB_0RA1LD_1RD1LA B1_1RB0LC_1LC1RB_0RA1LD_1RD1LA 6 24 p j' [] []).
    + exact run_ovf_1RB0LC_1LC1RB_0RA1LD_1RD1LA.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB0LC_1LC1RB_0RA1LD_1RD1LA p j' E).
    + exact (geo_1RB0LC_1LC1RB_0RA1LD_1RD1LA p j' E).
    + lia.
