(** ** Bootstrap *)

Lemma boot_1RB0LC_1LC1RB_0RA1LD_1RD1LA : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 36.
  assert (H : match csteps tm 36 c0 with
