Lemma gsi_1RB0LC_1LC1RB_0RB1LD_0RD1LA : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_110_111_111 q0 ++ [S0]) [] j A0_1RB0LC_1LC1RB_0RB1LD_0RD1LA.
