Lemma gei_1RB0LC_1LC1RB_0RB1LD_1LA0RC : forall p j q0, cview p = (j, Some q0) ->
  lift (cden (Ap_Alph_110_111_111 q0 ++ [S0]) [] j A1_1RB0LC_1LC1RB_0RB1LD_1LA0RC) = lift (Cc (Pos.succ p)).
