  | StC, S0 => mk S0 DR StB | StC, S1 => mk S1 DL StD
  | StD, S0 => mk S1 DL StC | StD, S1 => mk S1 DL StA end.

(** Its mirror 1LB0RC_1RC1LB_0LB1RD_1RC1RA: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_1RB0LC_1LC1RB_0RB1LD_1LC1LA : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DL StB | StA, S1 => mk S0 DR StC
  | StB, S0 => mk S1 DR StC | StB, S1 => mk S1 DL StB
  | StC, S0 => mk S0 DL StB | StC, S1 => mk S1 DR StD
  | StD, S0 => mk S1 DR StC | StD, S1 => mk S1 DR StA end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB0LC_1LC1RB_0RB1LD_1LC1LA : list Instr := [].
Definition tmw_1RB0LC_1LC1RB_0RB1LD_1LC1LA : TM := tm_wrap_trs tmm_1RB0LC_1LC1RB_0RB1LD_1LC1LA pins_1RB0LC_1LC1RB_0RB1LD_1LC1LA.
Local Notation tm := tmw_1RB0LC_1LC1RB_0RB1LD_1LC1LA.

Lemma mirror_ok_1RB0LC_1LC1RB_0RB1LD_1LC1LA : mirror_tm tm_1RB0LC_1LC1RB_0RB1LD_1LC1LA = tmm_1RB0LC_1LC1RB_0RB1LD_1LC1LA.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

Definition Cc_1RB0LC_1LC1RB_0RB1LD_1LC1LA (p : positive) : cconf := (StB, (Ap_Alph_110_111_111 p ++ [S0], S1, [S1;S1;S1])).
Local Notation Cc := Cc_1RB0LC_1LC1RB_0RB1LD_1LC1LA.

(** ** The certificate *)

Definition A0_1RB0LC_1LC1RB_0RB1LD_1LC1LA : sconf := mkC StB (mkS [] [S1;S1;S1] 1 0 [S1;S1;S0]) S1 (mkS [S1;S1;S1] [] 0 0 []).
Definition A1_1RB0LC_1LC1RB_0RB1LD_1LC1LA : sconf := mkC StB (mkS [] [S1;S1;S0] 1 0 [S1;S1;S1]) S1 (mkS [S1;S1;S1;S0] [] 0 0 []).
Definition chi_1RB0LC_1LC1RB_0RB1LD_1LC1LA : list lstep := [SCycL 3 0; SWin 6; SCycR 3; SWin 3; SWinR 17].

Lemma run_int_1RB0LC_1LC1RB_0RB1LD_1LC1LA : srun tm false true chi_1RB0LC_1LC1RB_0RB1LD_1LC1LA A0_1RB0LC_1LC1RB_0RB1LD_1LC1LA = Some (A1_1RB0LC_1LC1RB_0RB1LD_1LC1LA, 6, 26).
Proof. vm_compute. reflexivity. Qed.

Definition B0_1RB0LC_1LC1RB_0RB1LD_1LC1LA : sconf := mkC StB (mkS [] [S1;S1;S1] 1 0 [S1;S1;S1;S0]) S1 (mkS [S1;S1;S1] [] 0 0 []).
Definition B1_1RB0LC_1LC1RB_0RB1LD_1LC1LA : sconf := mkC StB (mkS [] [S1;S1;S0] 1 1 [S1;S1;S1]) S1 (mkS [S1;S1;S1] [] 0 0 []).
Definition cho_1RB0LC_1LC1RB_0RB1LD_1LC1LA : list lstep := [SCycL 3 0; SWin 8; SCycR 3; SWin 3; SWinR 11; SRotL 1; SFoldL 1].

Lemma run_ovf_1RB0LC_1LC1RB_0RB1LD_1LC1LA : srun tm true true cho_1RB0LC_1LC1RB_0RB1LD_1LC1LA B0_1RB0LC_1LC1RB_0RB1LD_1LC1LA = Some (B1_1RB0LC_1LC1RB_0RB1LD_1LC1LA, 6, 22).
Proof. vm_compute. reflexivity. Qed.

(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB0LC_1LC1RB_0RB1LD_1LC1LA : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_110_111_111 q0 ++ [S0]) [] j A0_1RB0LC_1LC1RB_0RB1LD_1LC1LA.
Proof.
  intros p j q0 E. destruct (Alph_110_111_111.cview_some_Alph_110_111_111 p j q0 E) as (H1 & _).
  unfold Cc_1RB0LC_1LC1RB_0RB1LD_1LC1LA, cden, A0_1RB0LC_1LC1RB_0RB1LD_1LC1LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

(** The lap ends on [S1;S1;S1;S0] where the anchor has [S1;S1;S1] -- one trailing blank,
    which [lift] cannot see. *)
Lemma gei_1RB0LC_1LC1RB_0RB1LD_1LC1LA : forall p j q0, cview p = (j, Some q0) ->
  lift (cden (Ap_Alph_110_111_111 q0 ++ [S0]) [] j A1_1RB0LC_1LC1RB_0RB1LD_1LC1LA) = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct (Alph_110_111_111.cview_some_Alph_110_111_111 p j q0 E) as (_ & H2).
  unfold Cc_1RB0LC_1LC1RB_0RB1LD_1LC1LA, cden, A1_1RB0LC_1LC1RB_0RB1LD_1LC1LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  change ([S1;S1;S1;S0]) with (([S1;S1;S1]) ++ [S0]).
  rewrite !lift_app_blank.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S1;S0] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_1RB0LC_1LC1RB_0RB1LD_1LC1LA : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E.
  exists (6 * j + 26), (cden (Ap_Alph_110_111_111 q0 ++ [S0]) [] j A1_1RB0LC_1LC1RB_0RB1LD_1LC1LA).
  split; [lia|]. split; [| exact (gei_1RB0LC_1LC1RB_0RB1LD_1LC1LA p j q0 E)].
  rewrite (gsi_1RB0LC_1LC1RB_0RB1LD_1LC1LA p j q0 E).
  exact (srun_sound tm false true chi_1RB0LC_1LC1RB_0RB1LD_1LC1LA A0_1RB0LC_1LC1RB_0RB1LD_1LC1LA A1_1RB0LC_1LC1RB_0RB1LD_1LC1LA 6 26
           run_int_1RB0LC_1LC1RB_0RB1LD_1LC1LA (Ap_Alph_110_111_111 q0 ++ [S0]) [] j
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

Lemma gso_1RB0LC_1LC1RB_0RB1LD_1LC1LA : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB0LC_1LC1RB_0RB1LD_1LC1LA.
Proof.
  intros p j E. destruct (Alph_110_111_111.cview_none_Alph_110_111_111 p j E) as (H1 & _).
  unfold Cc_1RB0LC_1LC1RB_0RB1LD_1LC1LA, cden, B0_1RB0LC_1LC1RB_0RB1LD_1LC1LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_1RB0LC_1LC1RB_0RB1LD_1LC1LA : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB0LC_1LC1RB_0RB1LD_1LC1LA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0LC_1LC1RB_0RB1LD_1LC1LA) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_110_111_111.cview_none_Alph_110_111_111 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB0LC_1LC1RB_0RB1LD_1LC1LA
             = (StB, (rep [S1;S1;S0] (S j) ++ [S1;S1;S1], S1, [S1;S1;S1]))).
  { unfold cden, B1_1RB0LC_1LC1RB_0RB1LD_1LC1LA, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StB, ((rep [S1;S1;S0] (S j) ++ [S1;S1;S1]) ++ [S0], S1, [S1;S1;S1]))).
  { unfold Cc_1RB0LC_1LC1RB_0RB1LD_1LC1LA. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_1RB0LC_1LC1RB_0RB1LD_1LC1LA. reflexivity.
Qed.

(** ** The lap *)

Lemma lap_1RB0LC_1LC1RB_0RB1LD_1LC1LA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB0LC_1LC1RB_0RB1LD_1LC1LA p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB0LC_1LC1RB_0RB1LD_1LC1LA B0_1RB0LC_1LC1RB_0RB1LD_1LC1LA B1_1RB0LC_1LC1RB_0RB1LD_1LC1LA 6 22 p j' [] []).
    + exact run_ovf_1RB0LC_1LC1RB_0RB1LD_1LC1LA.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB0LC_1LC1RB_0RB1LD_1LC1LA p j' E).
    + exact (geo_1RB0LC_1LC1RB_0RB1LD_1LC1LA p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_1RB0LC_1LC1RB_0RB1LD_1LC1LA : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 34.
  assert (H : match csteps tm 34 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 34 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB0LC_1LC1RB_0RB1LD_1LC1LA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0LC_1LC1RB_0RB1LD_1LC1LA = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB0LC_1LC1RB_0RB1LD_1LC1LA p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB0LC_1LC1RB_0RB1LD_1LC1LA p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB0LC_1LC1RB_0RB1LD_1LC1LA : forall t, ~ In t pins_1RB0LC_1LC1RB_0RB1LD_1LC1LA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n c', 0 < n /\ csteps tm n (Cc p0) = Some c'
                         /\ lift c' = lift (Cc (Pos.succ p0)))
    by exact lapi_1RB0LC_1LC1RB_0RB1LD_1LC1LA.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LC_1LC1RB_0RB1LD_1LC1LA [SCycL 3 0; SWin 8; SCycR 3; SWin 3; SWinR 8] (StA, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* A1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LC_1LC1RB_0RB1LD_1LC1LA [SCycL 3 0; SWin 7] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LC_1LC1RB_0RB1LD_1LC1LA [SCycL 3 0; SWin 4] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LC_1LC1RB_0RB1LD_1LC1LA [] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LC_1LC1RB_0RB1LD_1LC1LA [SCycL 3 0; SWin 8; SCycR 3; SWin 3; SWinR 2] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LC_1LC1RB_0RB1LD_1LC1LA [SCycL 3 0; SWin 5] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LC_1LC1RB_0RB1LD_1LC1LA [SCycL 3 0; SWin 8; SCycR 3; SWin 3; SWinR 1] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LC_1LC1RB_0RB1LD_1LC1LA [SCycL 3 0; SWin 6] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
Qed.

Theorem nqhtrm_1RB0LC_1LC1RB_0RB1LD_1LC1LA : NeverQuasiHaltsTr tmm_1RB0LC_1LC1RB_0RB1LD_1LC1LA.
Proof.
  apply (glue_neverqhtr tmm_1RB0LC_1LC1RB_0RB1LD_1LC1LA pins_1RB0LC_1LC1RB_0RB1LD_1LC1LA Cc 1).
  - exact boot_1RB0LC_1LC1RB_0RB1LD_1LC1LA.
  - intros p _. apply lap_1RB0LC_1LC1RB_0RB1LD_1LC1LA.
  - intros t Ht p _. apply fire_1RB0LC_1LC1RB_0RB1LD_1LC1LA. exact Ht.
Qed.

Theorem nqhtr_1RB0LC_1LC1RB_0RB1LD_1LC1LA : NeverQuasiHaltsTr tm_1RB0LC_1LC1RB_0RB1LD_1LC1LA.
Proof. apply (neverqhtr_mirror tm_1RB0LC_1LC1RB_0RB1LD_1LC1LA). rewrite mirror_ok_1RB0LC_1LC1RB_0RB1LD_1LC1LA. exact nqhtrm_1RB0LC_1LC1RB_0RB1LD_1LC1LA. Qed.

Theorem nonhalt_1RB0LC_1LC1RB_0RB1LD_1LC1LA : NonHalt tm_1RB0LC_1LC1RB_0RB1LD_1LC1LA.
Proof. apply never_qh_tr_nonhalt, nqhtr_1RB0LC_1LC1RB_0RB1LD_1LC1LA. Qed.

